final class CssSanitizer {
    private final Safelist safelist;

    CssSanitizer(Safelist safelist) {
        this.safelist = safelist;
    }

    /**
     Cleans an inline style value for the given tag.
     @param tagName the (lower-case) tag the attribute is on, for protocol lookup
     @param baseUri the owning element's base URI, for resolving relative references
     @param style the original style attribute value
     @return the cleaned style value, or {@code null} if no declaration survives (the attribute must be removed)
     */
    String clean(String tagName, String baseUri, String style) {
        Set<java.util.regex.Pattern> unused = null;
        java.util.Set<String> protocols = safelist.styleProtocols(tagName);
        StringBuilder cleaned = StringUtil.borrowBuilder();

        int length = style.length();
        int pos = 0;
        char quote = 0; // 0, or '"' / '\'' while inside a quoted string
        int parens = 0;
        boolean keptAny = false;

        while (pos <= length) {
            int start = pos;
            while (pos < length) {
                char c = style.charAt(pos);
                if (quote != 0) {
                    if (c == quote) quote = 0;
                } else if (c == '"' || c == '\'') {
                    quote = c;
                } else if (c == '(') {
                    parens++;
                } else if (c == ')') {
                    if (parens > 0) parens--; // an unmatched ')' is plain text, like in a browser
                } else if (c == ';' && parens == 0) {
                    break;
                }
                pos++;
            }

            String declaration = style.substring(start, pos);
            if (isSafeDeclaration(declaration, baseUri, protocols)) {
                if (keptAny) cleaned.append(';');
                cleaned.append(declaration);
                keptAny = true;
            }

            if (pos >= length) break;
            pos++; // step past the ';' separator
        }

        if (!keptAny) {
            StringUtil.releaseBuilderVoid(cleaned);
            return null;
        }
        return StringUtil.releaseBuilder(cleaned);
    }

    /**
     Validates one declaration (without its trailing semicolon). Whitespace-only and empty declarations are
     harmless and kept; declarations referencing external resources are put through the URL rules.
     */
    private boolean isSafeDeclaration(String declaration, String baseUri, java.util.Set<String> protocols) {
        int length = declaration.length();

        // locate the property, then the value (everything after the first top-level colon)
        int colon = -1;
        int i = 0;
        while (i < length) {
            char c = declaration.charAt(i);
            if (c == ':') { colon = i; break; }
            if (c == '(' || c == '"' || c == '\'') break; // no valid property run: malformed
            i++;
        }
        if (colon < 0) {
            // no colon: a stray token (e.g. an empty declaration from ";;"). Harmless if blank, else malformed
            return StringUtil.isBlank(declaration);
        }

        String property = declaration.substring(0, colon).trim();
        String value = declaration.substring(colon + 1);
        if (property.isEmpty()) return false; // malformed, e.g. ": red"
        if (StringUtil.isBlank(value)) return false; // a declaration with no value is not valid CSS

        // property name tokens must be identifier-like; case and surrounding whitespace must not matter
        for (int p = 0, plen = property.length(); p < plen; p++) {
            if (!isIdentifierChar(property.charAt(p))) return false;
        }

        // an @import at-rule smuggled into the declaration (browsers ignore it inline, but be defensive)
        String trimmedValue = stripLeadingCssWhitespace(value);
        if (startsWithIdent(trimmedValue, ImportIdent)) return false; // @import is handled tokenized below; defensive

        return isSafeValue(value, baseUri, protocols);
    }

    private static final String ImportIdent = "import";

    /**
     Walks the declaration value, validating every external reference found: an {@code @import} rule or a
     {@code url(...)}. Plain identifiers, strings (e.g. {@code font-family: 'Calibri'}), and other functional
     notation are left untouched.
     */
    private boolean isSafeValue(String value, String baseUri, java.util.Set<String> protocols) {
        int length = value.length();
        int i = 0;
        while (i < length) {
            char c = value.charAt(i);
            if (c == '"' || c == '\'') {
                // quoted string: content is not a reference unless this is an @import string stylesheet
                int stringStart = i;
                i = skipString(value, i, c);
                // only meaningful after an "@import" token; that case is caught via the at-rule scan below
                continue;
            }
            if (isCssWhitespace(c) || c == ')') { i++; continue; }

            if (c == '@') {
                // at-rule: only "@import <url>" is a reference; any other at-rule is not valid in a declaration
                int start = i + 1;
                int end = start;
                while (end < length && isIdentifierChar(value.charAt(end))) end++;
                String name = value.substring(start, end).toLowerCase(java.util.Locale.ROOT);
                if (!name.equals(ImportIdent)) return false;
                String ref = firstReference(value, end, baseUri, protocols);
                return ref != null && isSafeUrl(ref, baseUri, protocols);
            }

            // scan for the next identifier-ish run
            if (isIdentifierStart(c) || c == '-') {
                int start = i;
                while (i < length && (isIdentifierChar(value.charAt(i)) || value.charAt(i) == '\\')) i++;
                String fn = decodeIdent(value.substring(start, i)).toLowerCase(java.util.Locale.ROOT);
                int j = i;
                while (j < length && isCssWhitespace(value.charAt(j))) j++;
                if (fn.equals("url") && j < length && value.charAt(j) == '(') {
                    UrlToken url = readUrlFunction(value, j);
                    if (url == null || !isSafeUrl(url.url, baseUri, protocols)) return false;
                    i = url.next;
                    continue;
                }
                if (fn.equals(ImportIdent)) {
                    // "import" without '@' is an ordinary identifier in declaration position, not a rule
                }
                // other function names (rgb(...), calc(...), ...): descend through the parentheses to keep
                // scanning, so a nested url() cannot hide
                if (j < length && value.charAt(j) == '(') {
                    i = j + 1;
                    continue;
                }
                continue;
            }
            i++;
        }
        return true;
    }

    /** Finds the first reference (url(...) or bare string) after an {@code @import} keyword. */
    private String firstReference(String value, int from, String baseUri, java.util.Set<String> protocols) {
        int length = value.length();
        int i = from;
        while (i < length && isCssWhitespace(value.charAt(i))) i++;
        if (i >= length) return null;
        char c = value.charAt(i);
        if (c == '"' || c == '\'') {
            int end = skipString(value, i, c);
            return unescapeCss(value.substring(i + 1, end - 1));
        }
        // expect url(...)
        int start = i;
        while (i < length && isIdentifierChar(value.charAt(i))) i++;
        if (!value.substring(start, i).equalsIgnoreCase("url")) return null;
        while (i < length && isCssWhitespace(value.charAt(i))) i++;
        if (i >= length || value.charAt(i) != '(') return null;
        UrlToken url = readUrlFunction(value, i);
        return url == null ? null : url.url;
    }

    /** Holds a parsed {@code url(...)} reference and the index immediately after the closing parenthesis. */
    private static final class UrlToken {
        final String url;
        final int next;
        UrlToken(String url, int next) { this.url = url; this.next = next; }
    }

    /**
     Reads a {@code url( ... )} token starting at the opening parenthesis. Supports the quoted form
     ({@code url("x")}) and the unquoted form ({@code url(x)}). A missing closing quote or parenthesis
     consumes the rest of the value without throwing. Returns {@code null} if the content is not a single
     syntactically valid reference (e.g. trailing junk inside the quotes or two refs in one).
     */
    private static UrlToken readUrlFunction(String value, int openParen) {
        int length = value.length();
        int i = openParen + 1;
        while (i < length && isCssWhitespace(value.charAt(i))) i++;
        if (i >= length) return null;

        char c = value.charAt(i);
        String raw;
        if (c == '"' || c == '\'') {
            int contentStart = i + 1;
            int end = skipString(value, i, c); // index after closing quote (== length if unterminated)
            raw = value.substring(contentStart, Math.min(end - 1, length));
            i = end;
            // after a quoted URL only whitespace and an optional ')' may follow
            while (i < length && isCssWhitespace(value.charAt(i))) i++;
            if (i < length && value.charAt(i) == ')') i++;
            else if (i != length) return null; // junk where the closer should be: malformed
        } else {
            // unquoted: runs to the first ')' or top-level whitespace; escapes allowed
            StringBuilder sb = new StringBuilder();
            boolean closed = false;
            while (i < length) {
                char u = value.charAt(i);
                if (u == ')') { closed = true; i++; break; }
                if (isCssWhitespace(u)) break; // whitespace ends an unquoted URL; expect only ws + ')' after
                if (u == '"' || u == '\'') return null; // a quote may not appear inside an unquoted URL
                if (u == '\\' && i + 1 < length) { sb.append(u); sb.append(value.charAt(i + 1)); i += 2; }
                else { sb.append(u); i++; }
            }
            if (!closed) {
                int j = i;
                while (j < length && isCssWhitespace(value.charAt(j))) j++;
                if (j < length && value.charAt(j) == ')') { closed = true; i = j + 1; }
            }
            if (!closed && i != length) return null; // trailing junk
            if (!closed) { /* unterminated at end of value: treat the consumed text as the reference */ }
            raw = sb.toString();
        }
        if (StringUtil.isBlank(raw)) return null;
        return new UrlToken(unescapeCss(raw), i);
    }

    /** Returns the index just past the end of a quoted string starting at {@code start}; never throws if unterminated. */
    private static int skipString(String value, int start, char quote) {
        int i = start + 1, length = value.length();
        while (i < length) {
            char c = value.charAt(i);
            if (c == '\\' && i + 1 < length) { i += 2; continue; } // escaped char (incl. escaped quote/newline)
            if (c == quote) return i + 1;
            i++;
        }
        return length; // unterminated: consume to end
    }

    /**
     Resolves and validates one CSS URL reference against the same rules as an HTML URL attribute:
     no control characters, CSS-escape- and percent-decoding cannot reveal a forbidden scheme,
     protocol-relative and relative references resolve against the document base, and undeterminable
     references are rejected.
     */
    private boolean isSafeUrl(String rawUrl, String baseUri, java.util.Set<String> protocols) {
        String url = rawUrl.trim();
        if (url.isEmpty()) return false;

        // control characters and HTML-significant bytes are never legal in a CSS reference (HTML entities are
        // already decoded by the parser; this catches literal control bytes and stray surrogates)
        for (int i = 0, len = url.length(); i < len; i++) {
            char c = url.charAt(i);
            if (c <= 0x1f || c == 0x7f) return false;
        }

        // normalize CSS backslash escapes (e.g. "j\61 vascript:", "\6a avascript:") before any scheme test
        String unescaped = unescapeCss(url);
        // percent-decoding can likewise reveal the scheme a browser will use
        String decoded = percentDecode(unescaped);
        String probe = stripControlChars(decoded);

        String scheme = literalScheme(probe);
        if (scheme != null) {
            scheme = scheme.toLowerCase(java.util.Locale.ROOT);
            if (scheme.equals("data")) return dataAllowed(probe, protocols);
            return protocols.contains(scheme) && isSoundAbsolute(probe, scheme);
        }

        // a leading "//" is a protocol-relative reference: it carries a host, so it is only acceptable when
        // the document base supplies a scheme that is allowed
        if (startsWith(probe, "//")) {
            String resolved = StringUtil.resolve(baseUri, probe);
            if (resolved.isEmpty()) return false;
            String resolvedScheme = literalScheme(resolved);
            return resolvedScheme != null && protocols.contains(resolvedScheme);
        }

        // otherwise a relative reference: resolve against the document base when one exists
        if (StringUtil.isBlank(baseUri)) return false; // no base to decide against: deny
        String resolved = StringUtil.resolve(baseUri, probe);
        if (resolved.isEmpty()) {
            // resolution failed: allow only when it clearly carries no scheme (defensive), otherwise deny
            return literalScheme(probe) == null && safelist.preserveRelativeLinks();
        }
        String resolvedScheme = literalScheme(resolved);
        if (resolvedScheme == null) return false;
        if (!protocols.contains(resolvedScheme)) return false;
        // an absolute http(s) URL still needs a host; resolve() normalizes those, but double-check other schemes
        return isSoundAbsolute(resolved, resolvedScheme);
    }

    /** A {@code data:} URL survives only if {@code data} is explicitly allowed and its media type is safe. */
    private static boolean dataAllowed(String url, java.util.Set<String> protocols) {
        if (!protocols.contains("data")) return false;
        int comma = url.indexOf(',');
        if (comma < 0) return false; // a data URL must carry data
        String meta = url.substring("data:".length(), comma).trim().toLowerCase(java.util.Locale.ROOT);
        // strip ";base64" and any parameters, keeping the media type
        int semi = meta.indexOf(';');
        String mediaType = semi >= 0 ? meta.substring(0, semi).trim() : meta;
        if (mediaType.isEmpty()) mediaType = "text/plain"; // per spec, an omitted type defaults to text/plain
        return isSafeDataMediaType(mediaType);
    }

    /** Only image media types that cannot carry active content are allowed; {@code text/html} etc. are refused. */
    private static boolean isSafeDataMediaType(String mediaType) {
        if (mediaType.startsWith("image/")) {
            String subtype = mediaType.substring("image/".length());
            // svg can carry script; the rest are inert raster/vector image formats
            return !subtype.equals("svg+xml") && !subtype.isEmpty();
        }
        return false;
    }

    /** Verifies an absolute URL of a known scheme is structurally usable (an http(s) URL needs a host). */
    private static boolean isSoundAbsolute(String url, String scheme) {
        if (scheme.equals("http") || scheme.equals("https")) {
            int schemeEnd = url.indexOf(':');
            String rest = schemeEnd + 3 <= url.length() ? url.substring(schemeEnd + 3) : ""; // past "://"
            if (!url.startsWith("//", schemeEnd + 1)) return false;
            // host runs to the first '/', '?', or '#'
            int hostEnd = rest.length();
            for (int k = 0; k < rest.length(); k++) {
                char c = rest.charAt(k);
                if (c == '/' || c == '?' || c == '#') { hostEnd = k; break; }
            }
            return hostEnd > 0;
        }
        return true;
    }

    /**
     Returns the lower-cased scheme terminated by a literal colon, when the run before it is a legal scheme
     (so {@code x%3Ay}, {@code /a:b}, or a reference without a colon yields {@code null}). The argument has
     already had CSS escapes and percent escapes normalized, so this cannot be fooled by either.
     */
    private static String literalScheme(String url) {
        int colon = url.indexOf(':');
        if (colon <= 0) return null;
        String head = url.substring(0, colon);
        if (head.length() > 0 && (head.charAt(0) == '/' || head.charAt(0) == '?' || head.charAt(0) == '#'))
            return null;
        for (int i = 0; i < head.length(); i++) {
            char c = head.charAt(i);
            boolean schemeChar = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
                || (c >= '0' && c <= '9') || c == '+' || c == '-' || c == '.';
            if (!schemeChar) return null;
        }
        if (!isAsciiAlpha(head.charAt(0))) return null;
        return head; // caller lower-cases
    }

    /**
     Decodes CSS character escapes: {@code \\6A avascript}, {@code \\00006a}, and similar become the character a
     browser would read, so an obfuscated scheme is visible to the protocol checks. A backslash before any other
     character simply removes the backslash (CSS treats it as an escape of that literal character). Incomplete
     escapes at end of input are handled without throwing.
     */
    static String unescapeCss(String value) {
        if (value.indexOf('\\') == -1) return value;
        int length = value.length();
        StringBuilder sb = new StringBuilder(length);
        int i = 0;
        while (i < length) {
            char c = value.charAt(i);
            if (c == '\\' && i + 1 < length) {
                char next = value.charAt(i + 1);
                if (isHex(next)) {
                    int j = i + 1;
                    int hexStart = j;
                    while (j < length && j - hexStart < 6 && isHex(value.charAt(j))) j++;
                    int code = Integer.parseInt(value.substring(hexStart, j), 16);
                    // one whitespace after a hex escape is the terminator
                    if (j < length && isCssWhitespace(value.charAt(j))) j++;
                    if (code != 0 && (code < 0xD800 || code > 0xDFFF)) sb.appendCodePoint(code == 0 ? 0xFFFD : code);
                    i = j;
                    continue;
                } else {
                    sb.append(next); // escaped literal (quote, paren, backslash, ...)
                    i += 2;
                    continue;
                }
            }
            sb.append(c);
            i++;
        }
        return sb.toString();
    }

    /** Decodes a run of identifier characters that may contain CSS escapes, returning the literal identifier. */
    private static String decodeIdent(String value) {
        return unescapeCss(value);
    }

    /** Leniently percent-decodes {@code %XX} escapes; malformed escapes are left intact. Never throws. */
    private static String percentDecode(String value) {
        int length = value.length();
        if (length < 3 || value.indexOf('%') == -1) return value;
        StringBuilder sb = null;
        int i = 0;
        while (i < length) {
            char c = value.charAt(i);
            if (c == '%' && i + 2 < length
                && isHex(value.charAt(i + 1)) && isHex(value.charAt(i + 2))) {
                if (sb == null) { sb = new StringBuilder(length); sb.append(value, 0, i); }
                int hi = Character.digit(value.charAt(i + 1), 16);
                int lo = Character.digit(value.charAt(i + 2), 16);
                sb.append((char) ((hi << 4) | lo));
                i += 3;
                continue;
            }
            if (sb != null) sb.append(c);
            i++;
        }
        return sb != null ? sb.toString() : value;
    }

    /** Removes ASCII control characters (0x00-0x1F and DEL), which browsers ignore when reading a URL. */
    private static String stripControlChars(String value) {
        int length = value.length();
        StringBuilder stripped = null;
        for (int i = 0; i < length; i++) {
            char c = value.charAt(i);
            if (c <= 0x1f || c == 0x7f) {
                if (stripped == null) {
                    stripped = new StringBuilder(length);
                    stripped.append(value, 0, i);
                }
            } else if (stripped != null) {
                stripped.append(c);
            }
        }
        return stripped != null ? stripped.toString() : value;
    }

    private static boolean isHex(char c) {
        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
    }

    private static boolean isAsciiAlpha(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
    }

    private static boolean isIdentifierStart(char c) {
        return isAsciiAlpha(c) || c == '_';
    }

    /** CSS identifier body characters when written literally (escapes and non-ASCII handled separately). */
    private static boolean isIdentifierChar(char c) {
        return isAsciiAlpha(c) || (c >= '0' && c <= '9') || c == '_' || c == '-';
    }

    private static boolean isCssWhitespace(char c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
    }

    private static String stripLeadingCssWhitespace(String value) {
        int i = 0;
        while (i < value.length() && isCssWhitespace(value.charAt(i))) i++;
        return value.substring(i);
    }

    private static boolean startsWithIdent(String value, String ident) {
        return value.regionMatches(true, 0, ident, 0, ident.length());
    }

    private static boolean startsWith(String value, String prefix) {
        return value.startsWith(prefix);
    }
}

