 see whether that nesting ever closes before the end. Used to decide whether a semicolon is part of a
 nested construct (string, comment, or parenthesized value) or a recovery point for an opener that is
 never closed.
 */
private static boolean nestingClosesLater(String value, int from, int openParens, char openQuote, boolean openComment) {
    int length = value.length();
    if (openComment) return value.indexOf("*/", from) >= 0;
    if (openQuote != 0) {
        for (int i = from; i < length; i++) {
            char c = value.charAt(i);
            if (c == '\\' && i + 1 < length) { i++; continue; }
            if (c == openQuote) return true;
        }
        return false;
    }

    int parens = openParens;
    char quote = 0;
    boolean inComment = false;
    int pos = from;
    while (pos < length) {
        char c = value.charAt(pos);
        if (inComment) {
            if (c == '*' && pos + 1 < length && value.charAt(pos + 1) == '/') { inComment = false; pos += 2; continue; }
            pos++;
        } else if (quote != 0) {
            if (c == '\\' && pos + 1 < length) { pos += 2; continue; }
            if (c == quote) quote = 0;
            pos++;
        } else if (c == '/' && pos + 1 < length && value.charAt(pos + 1) == '*') {
            inComment = true; pos += 2;
        } else if (c == '"' || c == '\'') {
            quote = c; pos++;
        } else if (c == '(') {
            parens++; pos++;
        } else if (c == ')') {
            parens--; pos++;
            if (parens == 0) return true;
        } else {
            pos++;
        }
    }
    return false;
}

