/**
 Validates one unit and, when it holds a real safe declaration, appends it to the output. Empty or
 whitespace units (from leading, trailing, or repeated semicolons) produce nothing but are not
 rejections.
 @return whether a declaration was appended
 */
private boolean appendSafe(String unit, boolean broken, String baseUri, Set<String> protocols,
                           boolean preserveRelative, StringBuilder out, boolean alreadyKept) {
    String trimmed = unit.trim();
    if (trimmed.isEmpty()) return false; // blank unit: silently elide, no separator emitted for it
    if (broken || !isSafeDeclaration(unit, baseUri, protocols, preserveRelative)) return false;

    if (alreadyKept || out.length() > 0) out.append(';');
    out.append(unit);
    return true;
}

