String clean(String tagName, String baseUri, String style) {
    Set<String> protocols = safelist.styleProtocols(tagName);
    boolean preserveRelative = safelist.preserveRelativeLinks();
    StringBuilder cleaned = StringUtil.borrowBuilder();
    boolean keptAny = false;

    int length = style.length();
    int start = 0;
    int pos = 0;
    char quote = 0;          // 0, or '"' / '\'' while inside a quoted string
    int parens = 0;          // parenthesis depth outside strings/comments
    boolean inComment = false;

    while (pos < length) {
        char c = style.charAt(pos);

        // A ';' inside nesting only terminates the unit when that nesting is never closed. Otherwise the
        // semicolon is part of the nested construct (e.g. content: 'a; b').
        if (c == ';' && (quote != 0 || inComment || parens > 0)) {
            if (!nestingClosesLater(style, pos + 1, parens, quote, inComment)) {
                // the opener never closes: drop this broken unit here and recover, so later safe
                // declarations are not swallowed into the bad value
                if (appendSafe(style.substring(start, pos), true, baseUri, protocols, preserveRelative, cleaned))
                    keptAny = true;
                start = pos + 1;
                quote = 0;
                inComment = false;
                parens = 0;
            }
            pos++;
            continue;
        }

        if (inComment) {
            if (c == '*' && pos + 1 < length && style.charAt(pos + 1) == '/') { inComment = false; pos += 2; continue; }
            pos++;
            continue;
        }
        if (quote != 0) {
            if (c == '\\' && pos + 1 < length) { pos += 2; continue; } // escaped char, incl. escaped quote
            if (c == quote) quote = 0;
            pos++;
            continue;
        }
        if (c == '/' && pos + 1 < length && style.charAt(pos + 1) == '*') { inComment = true; pos += 2; continue; }
        if (c == '"' || c == '\'') { quote = c; pos++; continue; }
        if (c == '(') { parens++; pos++; continue; }
        if (c == ')') { if (parens > 0) parens--; pos++; continue; }

        if (c == ';') {
            if (appendSafe(style.substring(start, pos), false, baseUri, protocols, preserveRelative, cleaned))
                keptAny = true;
            start = pos + 1;
            pos++;
            continue;
        }
        pos++;
