    @Test void srcsetKeepsOriginalOrderAndDescriptors() {
        Safelist safelist = srcsetSafelist().preserveRelativeLinks(true);
        String html = "<img srcset='https://a.example/1 1x, javascript:drop 2x, https://b.example/2 300w, "
