 @param baseUri the owning element's base URI, for resolving relative references
 @param style the original style attribute value
 @return the cleaned style value, or {@code null} if no declaration survives (the attribute must be removed)
 */
String clean(String tagName, String baseUri, String style) {
    Set<String> protocols = safelist.styleProtocols(tagName);
    boolean preserveRelative = safelist.preserveRelativeLinks();
    StringBuilder cleaned = StringUtil.borrowBuilder();
    boolean keptAny = false;

    int length = style.length();
    int scanFrom = 0;
    Set<Integer> unclosedOpeners = unclosedOpeners(style, scanFrom); // openers that never get a close

    int start = 0;
    int pos = 0;
    char quote = 0;          // 0, or '"' / '\'' while inside a quoted string
    Deque<Integer> openStack = new ArrayDeque<>(); // positions of comment/quote/'(' openers
    boolean inComment = false;

    while (pos < length) {
        char c = style.charAt(pos);

        // A ';' inside nesting belongs to that nested construct (e.g. content: 'a; b') unless the
        // innermost opener is never closed; in that case recover here so later declarations survive.
        if (c == ';' && !openStack.isEmpty()) {
            if (unclosedOpeners.contains(openStack.peek())) {
                if (appendSafe(style.substring(start, pos), true, baseUri, protocols, preserveRelative, cleaned))
                    keptAny = true;
                start = pos + 1;
                quote = 0;
                inComment = false;
                openStack.clear();
                // the discarded opener masked the remainder's nesting; rescan it for further recoveries
                scanFrom = pos + 1;
                unclosedOpeners = unclosedOpeners(style, scanFrom);
            }
            pos++;
            continue;
        }

        if (inComment) {
            if (c == '*' && pos + 1 < length && style.charAt(pos + 1) == '/') {
                inComment = false; openStack.pop(); pos += 2; continue;
            }
            pos++;
            continue;
        }
        if (quote != 0) {
            if (c == '\\' && pos + 1 < length) { pos += 2; continue; } // escaped char, incl. escaped quote
            if (c == quote) { quote = 0; openStack.pop(); }
            pos++;
            continue;
        }
        if (c == '/' && pos + 1 < length && style.charAt(pos + 1) == '*') {
            inComment = true; openStack.push(pos); pos += 2; continue;
        }
        if (c == '"' || c == '\'') { quote = c; openStack.push(pos); pos++; continue; }
        if (c == '(') { openStack.push(pos); pos++; continue; }
        if (c == ')' && !openStack.isEmpty() && style.charAt(openStack.peek()) == '(') { openStack.pop(); pos++; continue; }

        if (c == ';') {
            if (appendSafe(style.substring(start, pos), false, baseUri, protocols, preserveRelative, cleaned))
                keptAny = true;
            start = pos + 1;
            pos++;
            continue;
        }
        pos++;
    }

    // a final unit whose nesting never closes is malformed
    if (start < length) {
        if (appendSafe(style.substring(start), !openStack.isEmpty(), baseUri, protocols, preserveRelative, cleaned))
            keptAny = true;
    }

    if (!keptAny) {
        StringUtil.releaseBuilderVoid(cleaned);
        return null;
    }
    return StringUtil.releaseBuilder(cleaned);
}

/**
 Runs one nesting-aware forward scan over {@code style[from..]} and returns the positions of openers
 (a {@code (}, a quote, or the {@code /} beginning a comment) that are never matched by a close before
 the end. Positions are absolute within {@code style}. The main pass uses the set to recover at a
 semicolon inside an unterminated construct in linear time; it is recomputed from the recovery point if
 such an opener is discarded.
 */
private static Set<Integer> unclosedOpeners(String style, int from) {
    int length = style.length();
    Deque<Integer> stack = new ArrayDeque<>();
    char quote = 0;
    boolean inComment = false;
    int pos = from;
    while (pos < length) {
        char c = style.charAt(pos);
        if (inComment) {
            if (c == '*' && pos + 1 < length && style.charAt(pos + 1) == '/') { inComment = false; stack.pop(); pos += 2; continue; }
            pos++;
            continue;
        }
        if (quote != 0) {
            if (c == '\\' && pos + 1 < length) { pos += 2; continue; }
            if (c == quote) { quote = 0; stack.pop(); }
            pos++;
            continue;
        }
        if (c == '/' && pos + 1 < length && style.charAt(pos + 1) == '*') { inComment = true; stack.push(pos); pos += 2; continue; }
        if (c == '"' || c == '\'') { quote = c; stack.push(pos); pos++; continue; }
        if (c == '(') { stack.push(pos); pos++; continue; }
        if (c == ')' && !stack.isEmpty() && style.charAt(stack.peek()) == '(') { stack.pop(); pos++; continue; }
        pos++;

