 * {@code (}, a quote, or the {@code /} beginning a comment), the index just past its matching close, or
 * {@code -1} if it never closes. Positions outside {@code from} and non-opener characters stay 0. The
 * main pass uses the table to recover at a semicolon in an unterminated construct in linear time.
 */
private static int[] matchOpeners(String style, int from) {
    int length = style.length();
    int[] closeAt = new int[length];
    Deque<Integer> stack = new ArrayDeque<>();
    char quote = 0;
    boolean inComment = false;
    int pos = from;
    while (pos < length) {
        char c = style.charAt(pos);
        if (inComment) {
            if (c == '*' && pos + 1 < length && style.charAt(pos + 1) == '/') {
                closeAt[stack.pop()] = pos + 2; inComment = false; pos += 2; continue;
            }
            pos++;
            continue;
        }
        if (quote != 0) {
            if (c == '\\' && pos + 1 < length) { pos += 2; continue; }
            if (c == quote) { closeAt[stack.pop()] = pos + 1; quote = 0; }
            pos++;
            continue;
        }
        if (c == '/' && pos + 1 < length && style.charAt(pos + 1) == '*') {
            inComment = true; stack.push(pos); pos += 2; continue;
        }
        if (c == '"' || c == '\'') { quote = c; stack.push(pos); pos++; continue; }
        if (c == '(') { stack.push(pos); pos++; continue; }
        if (c == ')' && !stack.isEmpty() && style.charAt(stack.peek()) == '(') {
            closeAt[stack.pop()] = pos + 1; pos++; continue;
        }
        pos++;
    }
    while (!stack.isEmpty()) closeAt[stack.pop()] = -1; // openers still open at EOF
